func (self class) Virtual(name string) reflect.Value {
	switch name {
	case "_pressed": return reflect.ValueOf(self._pressed);
	case "_toggled": return reflect.ValueOf(self._toggled);
	default: return gd.VirtualByName(Control.Advanced(self.AsControl()), name)
	}
}

func (self Instance) Virtual(name string) reflect.Value {
	switch name {
	case "_pressed": return reflect.ValueOf(self._pressed);
	case "_toggled": return reflect.ValueOf(self._toggled);
	default: return gd.VirtualByName(Control.Instance(self.AsControl()), name)
	}
}
